from collections import defaultdict, deque

def circulant_graph(n, offsets):
    edges = set()
    for v in range(n):
        for d in offsets:
            u = (v + d) % n
            if u != v:
                e = (min(u,v), max(u,v))
                edges.add(e)
    return sorted(edges)

def get_adj(n, edges):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def min_degree(n, edges):
    adj = get_adj(n, edges)
    return min(len(adj[v]) for v in range(n))

def max_independent_set_size(n, edges):
    adj = get_adj(n, edges)
    best = [0]
    def backtrack(candidates, size):
        if not candidates:
            if size > best[0]:
                best[0] = size
            return
        if size + len(candidates) <= best[0]:
            return
        v = candidates[0]
        new_candidates = [u for u in candidates[1:] if u not in adj[v]]
        backtrack(new_candidates, size + 1)
        backtrack(candidates[1:], size)
    backtrack(list(range(n)), 0)
    return best[0]

